UPDATE automation_timing SET occupying_firing_id=CASE WHEN occupying_firing_id IN (SELECT firing_id FROM automation_firings WHERE state='cancelled' AND batch_id IS NULL) THEN NULL ELSE occupying_firing_id END,waiting_firing_id=CASE WHEN waiting_firing_id IN (SELECT firing_id FROM automation_firings WHERE state='cancelled' AND batch_id IS NULL) THEN NULL ELSE waiting_firing_id END WHERE automation_id=?;
